\documentclass[tikz, border=10pt]{standalone}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}
\usepackage{ctex}

\begin{document}
\begin{tikzpicture}
\begin{axis}[
    title={\textbf{中国2019-2023年出生人口统计}},
    title style={font=\bfseries, yshift=10pt},
    width=10cm,
    height=7cm,
    ybar=5pt,
    bar width=20pt,
    symbolic x coords={2019, 2020, 2021, 2022, 2023},
    xtick=data,
    xticklabel style={font=\small},
    ymin=8000000,
    ymax=12000000,
    ylabel={出生人口（万人）},
    xlabel={年份},
    legend style={
        at={(1.03,0.5)},
        anchor=west,
        draw=black,
        fill=white,
        font=\small,
        legend columns=1
    },
    nodes near coords={\pgfmathprintnumber\pgfplotspointmeta},
    nodes near coords align={vertical},
    nodes near coords style={font=\tiny},
    every node near coord/.append style={/pgf/number format/fixed, /pgf/number format/precision=0},
    legend entries={出生人口},
    legend to name=legend1,
    axis background/.style={fill=white},
    grid=major,
    grid style={dashed, gray!30},
]
\addplot[
    fill=steelblue,
    draw=black,
    mark=*,
    mark size=4pt,
] coordinates {
    (2019, 1000)
    (2020, 920)
    (2021, 850)
    (2022, 956)
    (2023, 902)
};
\node[anchor=north west, font=\scriptsize] at (axis description cs:0.0,-0.15) {数据来源：国家统计局};
\end{axis}
\end{tikzpicture}
\end{document}
